// Expected values generated by Go (scratchpad/tm/main.go): time.Parse(RFC3339) + created.Before(revoked).
import { strictPurposeCheck } from '../../src/common/jsonmap/jsonmap';
import { parseDIDDocument } from '../../src/common/verification-method';
import { parseRFC3339Nanos } from '../../src/common/util/time';

const DID = 'did:example:purpose';
function setup(revoked: string) {
  const doc = parseDIDDocument({
    '@context': [], id: DID, authentication: [], assertionMethod: ['#key-1'],
    verificationMethod: [{ id: `${DID}#key-1`, type: 'EcdsaSecp256k1VerificationKey2019', controller: DID, publicKeyHex: '00', revoked }],
  });
  return { doc, vm: doc.verificationMethod[0] };
}
const check = (revoked: string, created: string) => {
  const { doc, vm } = setup(revoked);
  strictPurposeCheck(doc, vm, 'assertionMethod', created);
};

describe('strictPurposeCheck nanosecond revocation boundary (Go parity)', () => {
  const REV = '2026-06-01T00:00:00.000000500Z';
  it.each([
    ['2026-06-01T00:00:00.000000499Z', true],
    ['2026-06-01T00:00:00.0000005Z', false],
    ['2026-06-01T00:00:00.000000501Z', false],
    ['2026-06-01T07:00:00+07:00', true],
    ['2026-05-31T23:59:59.999999999Z', true],
    ['2026-06-01T00:00:00.0000005+00:00', false],
    ['2026-06-01T00:00:00,5Z', false],
  ])('created %s accepted=%s', (created, ok) => {
    if (ok) expect(() => check(REV, created)).not.toThrow();
    else expect(() => check(REV, created)).toThrow('is not earlier');
  });
  it('created == revoked at whole-second precision is rejected (Go table case)', () => {
    expect(() => check('2026-06-01T00:00:00Z', '2026-06-01T00:00:00Z')).toThrow('is not earlier');
    expect(() => check('2026-06-01T00:00:00Z', '2026-03-10T00:00:00Z')).not.toThrow();
  });
  it('same millisecond, different ns, revoked carried with an offset', () => {
    expect(() => check('2026-06-01T07:00:00.123456789+07:00', '2026-06-01T00:00:00.123456788Z')).not.toThrow();
    expect(() => check('2026-06-01T07:00:00.123456789+07:00', '2026-06-01T00:00:00.123456789Z')).toThrow('is not earlier');
  });
  it.each(['2026-06-01 00:00:00Z', '2026-06-01T00:00:00', '2026-06-01t00:00:00z', '2026-02-30T00:00:00Z', '2026-06-01T24:00:00Z', 'yesterday'])(
    'rejects non-RFC3339 created %j on a revoked key', (created) => {
      expect(() => check(REV, created)).toThrow('invalid proof.created timestamp');
    });
  it('a live key does not parse created (Go)', () => {
    const { doc, vm } = setup('2026-06-01T00:00:00Z');
    delete vm.revoked;
    expect(() => strictPurposeCheck(doc, vm, 'assertionMethod', 'yesterday')).not.toThrow();
  });
  it('parseRFC3339Nanos accepts the comma fraction like Go', () => {
    expect(parseRFC3339Nanos('2026-06-01T00:00:00,5Z')).toBe(parseRFC3339Nanos('2026-06-01T00:00:00.5Z'));
  });
});
